import React, { useState, useEffect } from 'react';
import { historyApi } from '../utils/api';
import toast from 'react-hot-toast';

export default function HistoryView() {
  const [summary, setSummary] = useState(null);
  const [records, setRecords] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    Promise.all([historyApi.getSummary(), historyApi.getAll()])
      .then(([s, r]) => { setSummary(s); setRecords(r); })
      .catch(() => toast.error('Failed to load history'))
      .finally(() => setLoading(false));
  }, []);

  if (loading) return <div className="text-gray-400 text-center py-20">Loading analytics...</div>;

  return (
    <div>
      <h2 className="text-2xl font-bold text-white mb-6">Order History & Analytics</h2>

      {summary && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
          <StatCard label="Total Orders" value={summary.totalOrders} color="blue" />
          <StatCard label="Total Revenue" value={`$${summary.totalRevenue.toFixed(2)}`} color="emerald" />
          <StatCard label="Avg Order Value" value={`$${summary.averageOrderValue.toFixed(2)}`} color="amber" />
          <StatCard label="Tracked from" value="Session Start" color="purple" />
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
        {summary?.topItems?.length > 0 && (
          <div className="bg-gray-800 rounded-xl p-5">
            <h3 className="text-lg font-semibold text-white mb-4">Top Items</h3>
            {summary.topItems.map((item, i) => (
              <div key={i} className="flex justify-between items-center py-2 border-b border-gray-700">
                <span className="text-gray-300">{item.name}</span>
                <span className="text-emerald-400 font-bold">{item.count} orders</span>
              </div>
            ))}
          </div>
        )}

        {summary?.revenueByCategory && Object.keys(summary.revenueByCategory).length > 0 && (
          <div className="bg-gray-800 rounded-xl p-5">
            <h3 className="text-lg font-semibold text-white mb-4">Revenue by Category</h3>
            {Object.entries(summary.revenueByCategory).map(([cat, rev]) => (
              <div key={cat} className="flex justify-between items-center py-2 border-b border-gray-700">
                <span className="text-gray-300 capitalize">{cat}</span>
                <span className="text-amber-400 font-bold">${rev.toFixed(2)}</span>
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="bg-gray-800 rounded-xl p-5">
        <h3 className="text-lg font-semibold text-white mb-4">All Orders ({records.length})</h3>
        {records.length === 0 ? (
          <p className="text-gray-500">No orders recorded yet. Place some orders to see history.</p>
        ) : (
          <div className="space-y-2 max-h-96 overflow-y-auto">
            {records.slice().reverse().map((record, i) => (
              <div key={i} className="bg-gray-700/50 rounded-lg p-3">
                <div className="flex justify-between text-sm">
                  <span className="text-white font-medium">Order #{record.orderId?.slice(0, 8)}</span>
                  <span className="text-emerald-400">${record.total?.toFixed(2)}</span>
                </div>
                <div className="flex gap-4 text-xs text-gray-400 mt-1">
                  <span>Table {record.tableId}</span>
                  <span>{record.pricingStrategy}</span>
                  <span>{new Date(record.timestamp).toLocaleTimeString()}</span>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

function StatCard({ label, value, color }) {
  const colors = {
    blue: 'border-blue-500 text-blue-400',
    emerald: 'border-emerald-500 text-emerald-400',
    amber: 'border-amber-500 text-amber-400',
    purple: 'border-purple-500 text-purple-400',
  };
  return (
    <div className={`bg-gray-800 border-l-4 ${colors[color]} rounded-xl p-4`}>
      <p className="text-gray-400 text-sm">{label}</p>
      <p className={`text-2xl font-bold ${colors[color].split(' ')[1]}`}>{value}</p>
    </div>
  );
}
